/** The next line's prefix when Enter is pressed at the end of a Markdown list item, or null. */
export function continueList(line) {
  const ordered = /^(\s*)(\d+)\. (.*)$/.exec(line);
  if (ordered) {
    if (!ordered[3].trim()) return null;
    return `${ordered[1]}${Number(ordered[2]) + 1}. `;
  }
  const bullet = /^(\s*)([-*]) (.*)$/.exec(line);
  if (bullet) {
    if (!bullet[3].trim()) return null;
    return `${bullet[1]}${bullet[2]} `;
  }
  return null;
}
